import { getSQLDate } from '@helpers/dateHelper';

import {
  IHikingScheduleAddDTO,
  IHikingScheduleDTO,
  IHikingScheduleUpdateDTO,
} from '../@types/hiking.backendTypes';
import { IHikingScheduleItem } from '../@types/hiking.baseTypes';

export const mapHikingScheduleItem = (backData: IHikingScheduleDTO): IHikingScheduleItem => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    link: backData.link,
    cost: backData.cost ? parseFloat(backData.cost) : null,
    currency: backData.id_cost_currency
      ? {
          id: +backData.id_cost_currency,
          name: backData.const_currency_name,
          shortName: backData.const_currency_short_name,
          symbol: backData.const_currency_symbol,
        }
      : null,
    article: backData.id_article ? { id: +backData.id_article, name: backData.article_name } : null,
    start: new Date(backData.d1),
    finish: new Date(backData.d2),
    is_self_sufficiency: backData.is_self_sufficiency == '1',
    routeObject: backData.id_route_object
      ? {
          id: +backData.id_route_object,
          name: backData.name_routeobject ?? '',
          description: backData.routeobject_description ?? '',
          distance: Number(backData.routeobject_distance),
          coordinates: backData.coordinates_routeobject
            ? JSON.parse(backData.coordinates_routeobject)
            : null,
          is_in_distance: backData.routeobject_is_in_distance == '1',
        }
      : undefined,
    foodAct: backData.id_food_act
      ? {
          id: +backData.id_food_act,
          name: backData.name_food_act ?? '',
          kkalTarget: Number(backData.food_act_norm_kkal) || undefined,
          kkalCurrent: Number(backData.kkal) || undefined,
        }
      : undefined,
  };
};

export const mapHikingScheduleItemToBackAdd =
  (id_hiking: number) =>
  (scheduleItem: IHikingScheduleItem): IHikingScheduleAddDTO => {
    return {
      id_hiking,
      d1: getSQLDate(scheduleItem.start),
      d2: getSQLDate(scheduleItem.finish),
      name: scheduleItem.name,
      is_self_sufficiency: scheduleItem.is_self_sufficiency ? '1' : '0',
      id_route_object: scheduleItem?.routeObject ? scheduleItem.routeObject.id : 0,

      id_food_act: scheduleItem?.foodAct ? scheduleItem.foodAct.id : 0,
      kkal: scheduleItem?.foodAct
        ? scheduleItem.foodAct.kkalCurrent?.toString() ||
          scheduleItem.foodAct.kkalTarget?.toString() ||
          ''
        : '',
      id_article: scheduleItem.article?.id ?? null,
      id_cost_currency: scheduleItem.currency?.id ?? null,
      description: scheduleItem?.description ?? '',
      link: scheduleItem?.link ?? '',
      cost: scheduleItem?.cost ? scheduleItem?.cost.toString() : '',
    };
  };

export const mapHikingScheduleItemToBackUpdate =
  (id_hiking: number) =>
  (scheduleItem: IHikingScheduleItem): IHikingScheduleUpdateDTO => {
    return {
      id: scheduleItem.id,
      ...mapHikingScheduleItemToBackAdd(id_hiking)(scheduleItem),
    };
  };

export const emptyScheduleName = 'Борьба с безудержным весельем';

export const getEmptyScheduleItem = (
  schedule: Partial<IHikingScheduleItem> = {},
): IHikingScheduleItem => {
  const storedDate = sessionStorage.getItem(`lastScheduleDate`);
  const start = storedDate ? new Date(storedDate) : new Date();
  return {
    id: 0,
    name: emptyScheduleName,
    description: null,
    link: null,
    cost: null,
    article: null,
    currency: null,
    is_self_sufficiency: false,
    start,
    finish: new Date(start.getTime() + 30 * 60 * 1000),
    routeObject: undefined,
    foodAct: undefined,
    ...schedule,
  };
};
